<?php require __DIR__.'/../config/bootstrap.php'; require_admin(); /* This check was missing: the POST handler below ran before includes/admin_header.php performed the login check, so anyone holding a CSRF token from the public contact form could add or delete records while signed out. */ $admin_title='Sectors'; if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$a=$_POST['action']??'';if($a==='save'){$id=(int)($_POST['id']??0);$title=post_text('title');$desc=post_text('description');$icon=post_text('icon','fa-solid fa-building');$sort=post_int('sort_order');$active=isset($_POST['active'])?1:0;if($title===''||$desc==='')throw new UserMessageException('Please enter both a sector title and a description before saving.');if($id)db()->prepare('UPDATE sectors SET title=?,description=?,icon=?,sort_order=?,active=? WHERE id=?')->execute([$title,$desc,$icon,$sort,$active,$id]);else db()->prepare('INSERT INTO sectors(title,description,icon,sort_order,active) VALUES(?,?,?,?,?)')->execute([$title,$desc,$icon,$sort,$active]);flash('success','Sector saved.');}elseif($a==='delete'){db()->prepare('DELETE FROM sectors WHERE id=?')->execute([post_int('id')]);flash('success','Sector deleted.');}header('Location: '.url('admin/sectors.php'));exit;}catch(Throwable $e){flash_exception($e);header('Location: '.url('admin/sectors.php'));exit;}}$edit=null;if(isset($_GET['edit'])){$st=db()->prepare('SELECT * FROM sectors WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$items=db()->query('SELECT * FROM sectors ORDER BY sort_order,id')->fetchAll();require __DIR__.'/../includes/admin_header.php'; ?><div class="admin-card"><h2><?=$edit?'Edit sector':'Add sector'?></h2><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-cols"><div><label>Title</label><input required name="title" value="<?=e($edit['title']??'')?>"></div><div><label>Description</label><input required name="description" value="<?=e($edit['description']??'')?>"></div><div><label>Icon class</label><input name="icon" value="<?=e($edit['icon']??'fa-solid fa-building')?>"></div><div><label>Sort order</label><input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></div></div><label class="check"><input type="checkbox" name="active" <?=($edit===null||!empty($edit['active']))?'checked':''?>> Show publicly</label><button class="admin-button">Save Sector</button></form></div><div class="admin-card"><table class="table"><thead><tr><th>Sector</th><th>Icon</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=e($x['title'])?><small><?=e($x['description'])?></small></td><td><i class="<?=e($x['icon'])?>"></i></td><td><?=!empty($x['active'])?'Visible':'Hidden'?></td><td class="actions"><a href="?edit=<?=(int)$x['id']?>">Edit</a><form method="post" data-confirm="Delete this sector?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/admin_footer.php'; ?>